CREATE TABLE IF NOT EXISTS data_rooms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,drive_folder_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS folders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),data_room_id uuid NOT NULL REFERENCES data_rooms(id) ON DELETE CASCADE,parent_id uuid REFERENCES folders(id) ON DELETE CASCADE,name text NOT NULL,drive_folder_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),data_room_id uuid NOT NULL REFERENCES data_rooms(id) ON DELETE CASCADE,folder_id uuid REFERENCES folders(id) ON DELETE SET NULL,name text NOT NULL,drive_file_id text UNIQUE,mime_type text,web_view_link text,modified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS drive_mappings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),drive_id text NOT NULL UNIQUE,entity_type text NOT NULL CHECK(entity_type IN ('data_room','folder','document')),entity_id uuid NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events(id bigserial PRIMARY KEY,event_type text NOT NULL,entity_type text,entity_id text,payload jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());